import 'dart:async';import 'package:flutter/material.dart';import 'package:sehatak/core/services/steps/steps_service.dart';import 'package:sehatak/core/services/health_tracking_service.dart';import 'package:sehatak/presentation/widgets/futuristic/glass_card.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_background.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_app_bar.dart';import 'package:sehatak/presentation/widgets/futuristic/holographic_number.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_period_selector.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_line_chart.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_stat_card.dart';
class StepTrackerScreen extends StatefulWidget{const StepTrackerScreen({super.key});@override State<StepTrackerScreen> createState()=>_S();}class _S extends State<StepTrackerScreen>{final s=StepsService.instance;StreamSubscription<StepsSnapshot>? sub;int steps=0,cal=0;double dist=0;List<double> chart=[];@override void initState(){super.initState();sub=s.updates.listen((x){if(mounted)setState((){steps=x.steps;cal=x.calories;dist=x.distance/1000;});});_init();}Future<void>_init()async{await s.startTracking();if(!mounted)return;setState((){steps=s.currentSteps;});final r=await HealthTrackingService.history('steps',days:30);if(mounted)setState(()=>chart=r.map((e)=>(e['value']as num?)?.toDouble()??0).where((e)=>e>0).toList().reversed.toList());}@override void dispose(){sub?.cancel();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(backgroundColor:const Color(0xFF0A0E1A),appBar:const FuturisticAppBar(title:'عداد الخطوات'),body:FuturisticBackground(glowColor:const Color(0xFF00E5A0),child:ListView(padding:const EdgeInsets.all(16),children:[GlassCard(glowColor:const Color(0xFF00E5A0),child:Column(children:[HolographicNumber(value:steps.toString(),unit:'خطوة اليوم',color:const Color(0xFF00E5A0),fontSize:64),const SizedBox(height:8),LinearProgressIndicator(value:(steps/10000).clamp(0,1),minHeight:8),const SizedBox(height:8),Text((steps/10000*100).round().toString()+'% من هدف 10,000',style:const TextStyle(color:Colors.white60))])),const SizedBox(height:12),Row(children:[FuturisticStatCard(icon:Icons.route,label:'المسافة',value:dist.toStringAsFixed(2)+' كم',color:const Color(0xFF00E5A0)),const SizedBox(width:8),FuturisticStatCard(icon:Icons.local_fire_department,label:'السعرات',value:cal.toString(),color:const Color(0xFFFF9F43))]),const SizedBox(height:12),GlassCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('تاريخ الخطوات',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w800)),const SizedBox(height:8),chart.length>1?F